content.text:
{
  "name": "旋转编码器",
  "name_en": "Rotary Encoder",
  "manufacturer": "",
  "description": "用于检测车轮或旋转轴脉冲计数的传感器，可根据计数与时间间隔估算速度、行驶距离和里程，常用于移动机器人或小车实验中的运动反馈与里程计测量。",
  "description_en": "A sensor that counts pulses from a wheel or rotating shaft and uses tick counts over time to estimate speed, traveled distance, and odometry for motion feedback in mobile robot or small vehicle experiments.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "循环更新编码器计数、时间间隔以及距离和里程估计。",
      "description_en": "Continuously update encoder tick counts, time intervals, and distance/odometry estimates."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程模式下输出当前编码器测得的运动状态，用于与控制循环配合运行。",
      "description_en": "Provide the current motion state measured by the encoder in threaded operation for use by a control loop."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止编码器更新线程。",
      "description_en": "Stop the encoder update thread."
    }
  ],
  "tag_hints": [
    "rotary encoder",
    "wheel odometry",
    "speed measurement",
    "distance tracking",
    "tick counting",
    "mobile robotics"
  ]
}

